function overlapBounds(bucketDt,grain,start,end){const periodStart=parseDateOnly(start),periodEnd=parseDateOnly(end);if(!periodStart||!periodEnd)return null;const inclusiveEnd=new Date(periodEnd.getTime()+24*3600*1000);const b0=bucketStart(bucketDt,grain),b1=nextBucket(b0,grain);const s=Math.max(b0.getTime(),periodStart.getTime()),e=Math.min(b1.getTime(),inclusiveEnd.getTime());return e>s?{start:new Date(s),end:new Date(e),hours:(e-s)/3600000}:null}
function overlapHours(bucketDt,grain,start,end){return overlapBounds(bucketDt,grain,start,end)?.hours||0}
function utcDayKey(dt){return `${dt.getUTCFullYear()}-${pad(dt.getUTCMonth()+1)}-${pad(dt.getUTCDate())}`}
function activeDaySet(rows){const sums=new Map();for(const r of(rows||[])){const day=String(r?.ts||'').slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(day))continue;const k1=Number(r?.inv1Kwh||0),k2=Number(r?.inv2Kwh||0),kt=Number(r?.totalKwh??r?.kwh??(k1+k2));sums.set(day,(sums.get(day)||0)+(Number.isFinite(kt)?kt:0))}return new Set([...sums.entries()].filter(([,v])=>v>0).map(([k])=>k))}
function activeHoursForBucket(bucketDt,grain,start,end,activeDays){const b=overlapBounds(bucketDt,grain,start,end);if(!b||!activeDays?.size)return 0;let cur=new Date(b.start),hours=0,guard=0;while(cur<b.end&&guard<4000){const dayStart=new Date(Date.UTC(cur.getUTCFullYear(),cur.getUTCMonth(),cur.getUTCDate()));const nextDay=new Date(dayStart);nextDay.setUTCDate(nextDay.getUTCDate()+1);const segEnd=new Date(Math.min(nextDay.getTime(),b.end.getTime()));if(activeDays.has(utcDayKey(cur)))hours+=(segEnd-cur)/3600000;cur=segEnd;guard++}return hours}
function activeDaysForBucket(bucketDt,grain,start,end,activeDays){const b=overlapBounds(bucketDt,grain,start,end);if(!b||!activeDays?.size)return 0;const seen=new Set();let cur=new Date(b.start),guard=0;while(cur<b.end&&guard<4000){const day=utcDayKey(cur);if(activeDays.has(day))seen.add(day);const nextDay=new Date(Date.UTC(cur.getUTCFullYear(),cur.getUTCMonth(),cur.getUTCDate()+1));cur=new Date(Math.min(nextDay.getTime(),b.end.getTime()));guard++}return seen.size}
function efficiency(kwh,capacityKw,hours){if(!(capacityKw>0)||!(hours>0))return null;return +(kwh/(capacityKw*hours)*100).toFixed(2)}
function fullLoadHours(kwh,capacityKw){if(!(capacityKw>0))return null;return +(kwh/capacityKw).toFixed(2)}
function avgDailyFullLoadHours(kwh,capacityKw,hours){if(!(capacityKw>0)||!(hours>0))return null;const days=hours/24;if(!(days>0))return null;return +(kwh/capacityKw/days).toFixed(2)}
function benchmarkStats(monthly,bucketDt,grain,start,end,activeDays){const b=overlapBounds(bucketDt,grain,start,end);if(!b||!Array.isArray(monthly)||!activeDays?.size)return{efficiency:null,generationHours:null,avgDailyGenerationHours:null};let cur=new Date(b.start),weighted=0,knownHours=0,eqHours=0,guard=0;while(cur<b.end&&guard<4000){const dayStart=new Date(Date.UTC(cur.getUTCFullYear(),cur.getUTCMonth(),cur.getUTCDate()));const nextDay=new Date(dayStart);nextDay.setUTCDate(nextDay.getUTCDate()+1);const segEnd=new Date(Math.min(nextDay.getTime(),b.end.getTime()));const h=(segEnd-cur)/3600000,cf=Number(monthly[cur.getUTCMonth()]);if(activeDays.has(utcDayKey(cur))&&Number.isFinite(cf)){weighted+=cf*h;knownHours+=h;eqHours+=h*cf/100}cur=segEnd;guard++}return{efficiency:knownHours?+(weighted/knownHours).toFixed(2):null,generationHours:knownHours?+eqHours.toFixed(2):null,avgDailyGenerationHours:knownHours?+(eqHours/(knownHours/24)).toFixed(2):null}}

